typedef float rational_t;

class vector3d {
public:
  rational_t x, y, z;

  inline vector3d() {}
  inline vector3d(const vector3d& v) { x = v.x; y = v.y; z = v.z; }

  bool is_valid() const {
    return x > -1e30f && x < 1e30f &&
           y > -1e30f && y < 1e30f &&
           z > -1e30f && z < 1e30f;
  }
};

class vector4d {
public:
  rational_t x, y, z, w;
};

class matrix4x4 {
public:
  vector4d x __attribute__((aligned(16)));
  vector4d y;
  vector4d z;
  vector4d w;
};

class po {
  matrix4x4 m;

public:
  inline const vector3d& get_position() const {
    return (const vector3d&)(m.w);
  }
};

class signal_list;

class signaller {
  unsigned int flags;
  signal_list* signals;

public:
  virtual ~signaller();
  virtual bool is_an_entity() const;
  virtual bool is_a_trigger() const;
  virtual void raise_signal(unsigned int idx) const;

private:
  virtual signal_list* construct_signal_list();

protected:
  virtual const char* get_signal_name(unsigned short idx) const;
};

class pstring;
class stringx;

class generic_interface {
public:
  virtual ~generic_interface();
  virtual bool get_ifc_num(const pstring&, rational_t&);
  virtual bool set_ifc_num(const pstring&, rational_t);
  virtual bool get_ifc_vec(const pstring&, vector3d&);
  virtual bool set_ifc_vec(const pstring&, const vector3d&);
  virtual bool get_ifc_str(const pstring&, stringx&);
  virtual bool set_ifc_str(const pstring&, const stringx&);
};

class bone;

class bone_interface : public generic_interface {
protected:
  bone* my_bone;

public:
  virtual ~bone_interface();
};

class link_interface : public bone_interface {
protected:
  bone* my_parent;
  bone* my_child;
  bone* my_brother;
  bool link_manages_abs_po;

public:
  virtual ~link_interface();
  bone* get_parent() const { return my_parent; }
  bone* get_first_child() const { return my_child; }
  bone* get_next_sibling() const { return my_brother; }
};

class sector;

class bone : public signaller {
protected:
  po my_rel_po;
  po* my_abs_po;
  po* my_handed_abs_po;
  int bone_id;
  sector* my_sector;
  int flip_axis;
  bool is_part_of_skeleton;
  link_interface* my_link_interface;

public:
  virtual ~bone();
  virtual int get_bone_idx();
  virtual void po_changed();

  bool has_link_ifc() const { return my_link_interface != 0; }
  link_interface* link_ifc() const { return my_link_interface; }
  const vector3d& get_abs_position() const {
    return my_abs_po->get_position();
  }
};

void bone::po_changed()
{

  vector3d pos=get_abs_position();
  if (!pos.is_valid())
    return;
  // update children if necessary
  if( has_link_ifc() )
  {
    bone* child_iterator = link_ifc()->get_first_child();
    for(; child_iterator;)
    {
      child_iterator->po_changed();
      if( child_iterator->has_link_ifc())
        child_iterator = child_iterator->link_ifc()->get_next_sibling();
      else
        break;
    }
  }
}
